    Bug 1742904 - Introduce MailServices.ab.clearCache(). r=aleca

    Instead of triggering the clearing of the address book cache by incrementing
    the mail.displayname.version preference, this patch introduces the more
    suitable helper method MailServices.ab.clearCache().

    Differential Revision: https://phabricator.services.mozilla.com/D274252

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 76e2c64ca21..702c7451c25 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -5044,9 +5044,9 @@ var threadPane = {
         break;
       case "addrbook-displayname-changed":
       case "custom-column-refreshed":
-        // addrbook-displayname-changed: This runs when mail.displayname.version
-        // preference observer is notified or the number of the
-        // mail.displayname.version preference has been updated.
+        // addrbook-displayname-changed: This runs when the cache of addressbook
+        // cards has been cleared because the display name of a contact changed,
+        // signaled by incrementing the mail.displayname.version preference.
         // custom-column-refreshed: This used to refresh just the column,
         // but now that filling the cells happens asynchronously, that's too
         // complicated, so it's better to invalidate the whole thing. Kept for
diff --git a/mail/modules/MailMigrator.sys.mjs b/mail/modules/MailMigrator.sys.mjs
index d0767b674f0..926cf84c0b2 100644
--- a/mail/modules/MailMigrator.sys.mjs
+++ b/mail/modules/MailMigrator.sys.mjs
@@ -139,10 +139,7 @@ export var MailMigrator = {
       if (currentUIVersion < 42) {
         // Update the display name version pref so we force clear the cache of
         // sender names.
-        Services.prefs.setIntPref(
-          "mail.displayname.version",
-          Services.prefs.getIntPref("mail.displayname.version", 0) + 1
-        );
+        MailServices.ab.clearCache();
       }

       if (currentUIVersion < 43) {
